      "4. Maximize $\\frac{3x}{x^2 + 4}$ by differentiating: $(x^2 + 4)(3) - 3x(2x) = 12 - 3x^2 = 0 \\implies x^2 = 4 \\implies x = 2\\text{ m}$."
