      "3. $V'(h) = \\pi(36 - \\frac{3h^2}{4}) = 0 \\implies 3h^2 = 144 \\implies h^2 = 48 \\implies h = 4\\sqrt{3}$.",
      "4. Base radius squared: $r^2 = 36 - \\frac{48}{4} = 36 - 12 = 24$.",
      "5. Maximum volume: $V = \\pi(24)(4\\sqrt{3}) = 96\\sqrt{3}\\pi$."
