      "2. Combined area: $A(r) = (\\frac{L - 2\\pi r}{4})^2 + \\pi r^2 = \\frac{L^2 - 4\\pi L r + 4\\pi^2 r^2}{16} + \\pi r^2$.",
      "3. Differentiating with respect to $r$:",
