    "difficulty": "hots",
    "questionEn": "Find the point on the x-axis that minimizes the sum of distances to $A(1, 2)$ and $B(5, 4)$.",
    "questionAr": "أوجد النقطة الواقعة على محور السينات التي تجعل مجموع بعديها عن النقطتين $A(1، 2)$ و $B(5، 4)$ أقل ما يمكن.",
