    "titleAr": "أقصر وتر لمثلث قائم محيط بمستطيل معلوم",
    "difficulty": "hots",
    "questionEn": "A right triangle is circumscribed about a rectangle of sides $a = 1$ and $b = 8$, with one corner at the right angle. Find the minimum possible length of the hypotenuse.",
    "questionAr": "مثلث قائم الزاوية محيط بمستطيل بعداه $a = 1$ و $b = 8$ بحيث يشترك رأس منه مع الزاوية القائمة. أوجد أقل طول ممكن لوتر هذا المثلث.",
    "optionsEn": [
      "$5\\sqrt{5}$",
      "$10$",
      "$9$",
      "$4\\sqrt{5}$"
    ],
    "optionsAr": [
      "5 جذر(5)",
      "10",
      "9",
      "4 جذر(5)"
    ],
    "correctAnswer": "$5\\sqrt{5}$",
    "correctIndex": 0,
    "hintEn": "This problem is mathematically equivalent to the shortest ladder over a wall of height 8 at distance 1.",
    "hintAr": "هذه المسألة مطابقة رياضياً لأقصر سلم يمر فوق سور ارتفاعه 8 ويبعد 1 عن المبنى.",
    "stepByStepSolutionEn": [
      "1. The hypotenuse length as a function of angle $\\theta$ is $L(\\theta) = \\frac{1}{\\cos\\theta} + \\frac{8}{\\sin\\theta}$.",
      "2. Minimizing $L(\\theta)$ yields $\\tan\\theta = \\sqrt[3]{8/1} = 2$.",
      "3. Then $\\cos\\theta = 1/\\sqrt{5}$ and $\\sin\\theta = 2/\\sqrt{5}$.",
      "4. Minimum hypotenuse length is $L = \\sqrt{5} + 4\\sqrt{5} = 5\\sqrt{5}$."
    ],
    "stepByStepSolutionAr": [
      "١. طول الوتر بدلالة الزاوية θ: ل(θ) = 1/جتا θ + 8/جا θ.",
      "٢. بتعظيم دالة الزاوية: ظا θ = الجذر التكعيبي لـ (8/1) = 2.",
      "٣. جتا θ = 1/جذر(5) وجا θ = 2/جذر(5).",
      "٤. أقل طول للوتر = جذر(5) + 4 جذر(5) = 5 جذر(5)."
    ],
    "teacherTipEn": "The mathematical equivalence between circumscribed triangles and shortest ladders reveals the unity of calculus optimization.",
    "teacherTipAr": "التطابق الرياضي بين المثلثات المحيطة وأقصر طول سلم يبرز وحدة وتناغم مسائل التفاضل والتحسين."
